import { readFile } from "node:fs/promises";
import { expect, it } from "vitest";
import { compileTokens } from "../src/tokens/compile.js";

const tokensFolder = new URL("../src/tokens/", import.meta.url);

// tokens.css is generated by make tokens (decision 0026), and kept in the repository.
it("keeps tokens.css up to date with tokens.json", async () => {
  const source: unknown = JSON.parse(
    await readFile(new URL("tokens.json", tokensFolder), "utf8"),
  );
  const written = await readFile(new URL("tokens.css", tokensFolder), "utf8");

  expect(written, "tokens.css is out of date: run make tokens").toBe(
    compileTokens(source),
  );
});
